async function api(action:string,args:any){const r=await fetch("actions",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action,args})});const j=await r.json();if(!r.ok||j.error) throw new Error(j.error||"Falha na conexão.");return j.data}
function CityArt(){const b=[{l:'2%',w:58,h:82},{l:'12%',w:78,h:128},{l:'26%',w:52,h:96},{l:'36%',w:88,h:150},{l:'52%',w:62,h:105},{l:'63%',w:82,h:138},{l:'77%',w:55,h:88},{l:'87%',w:70,h:122}];return <div className="city h-[210px] sm:h-[260px] rounded-[22px] border border-[var(--line)]"><div className="absolute inset-x-0 bottom-0 h-[36px] bg-[#071812] border-t border-emerald-300/30 z-10 flex items-end justify-between px-4 pb-1 text-[10px] tracking-widest text-emerald-200"><span>● CENTRO • 2.418 JOGADORES ONLINE</span><span className="hidden sm:inline">PRAÇA CENTRAL • 19:42</span></div>{b.map((x,i)=><div key={i} className="building" style={{left:x.l,width:x.w,height:x.h}}>{[12,32,52,72].map(y=><span key={y} className="window" style={{left:8,top:y}}/>)} {[12,32,52].map(y=><span key={y} className="window" style={{right:8,top:y+18}}/>)}<span className="absolute -top-2 left-1/2 -translate-x-1/2 w-2 h-2 rounded-full bg-cyan-300 shadow-[0_0_12px_#00e5ff]"/></div>)}<div className="absolute left-[48%] bottom-[36px] w-[90px] h-[90px] rounded-full border border-cyan-300/50 flex items-center justify-center text-cyan-200 text-[10px] text-center z-10 bg-cyan-400/10">PORTAL<br/>RA ATIVO</div></div>}

function Section({kicker,title,sub,children}:{kicker:string;title:string;sub?:string;children:React.ReactNode}){return <section><div className="flex items-center gap-2 text-[11px] tracking-[.22em] font-bold text-cyan-300"><span className="w-7 h-[2px] bg-gradient-to-r from-[#8b5cf6] via-[#00e5ff] to-[#00ff88]"/> {kicker}</div><h2 className="font-display text-[clamp(1.55rem,5vw,2.7rem)] leading-[1.05] font-black mt-3 [overflow-wrap:anywhere]">{title}</h2>{sub&&<p className="text-[var(--muted)] mt-3 max-w-[760px] text-[15px] leading-relaxed">{sub}</p>}<div className="mt-6 space-y-5">{children}</div></section>}
function H3({children}:{children:React.ReactNode}){return <h3 className="font-display text-lg sm:text-xl font-bold">{children}</h3>}
function P({children}:{children:React.ReactNode}){return <p className="text-[var(--muted)] leading-relaxed text-[15px]">{children}</p>}
function RarityBadge({name}:{name:string}){return <span className={`chip rarity-${name} !border-transparent`}><Gem size={12}/> {name.toUpperCase()}</span>}
function NftVisual({d,rIdx,size}:{d:typeof DISTRICTS[number];rIdx:number;size:number}){const r=RARITIES[rIdx]||RARITIES[1];return <div className="h-[150px] relative overflow-hidden" style={{background:`linear-gradient(135deg, ${d.color}55, #0b0b1e 55%, #2a1460 100%)`}}><div className="absolute inset-0 opacity-30" style={{background:`radial-gradient(circle at 25% 20%, ${d.color}, transparent 35%), radial-gradient(circle at 85% 80%, #8b5cf6, transparent 35%)`}}/><span className="absolute left-3 top-3 chip !bg-black/60 !text-white text-[10px]">CRYPYVERSE • #{String(size).padStart(4,'0')}</span><span className="absolute right-3 top-3"><RarityBadge name={r.name}/></span><span className="absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 text-[64px] drop-shadow-[0_0_22px_rgba(0,229,255,.65)]">{d.emoji}</span><span className="absolute left-3 bottom-3 chip !bg-black/60 !text-white"><MapPin size={12}/> {d.name} • {size} m²</span><span className="absolute right-3 bottom-3 text-[11px] font-bold text-emerald-300">● VERIFICADO</span></div>}

export default function App(){
 const [flat,setFlat]=useState(0); const [search,setSearch]=useState(''); const [open,setOpen]=useState(false); const [expanded,setExpanded]=useState(0);
 const [balance,setBalance]=useState(250000); const [amount,setAmount]=useState('50000'); const [transferTo,setTransferTo]=useState('Luna • Residencial');
 const [statement,setStatement]=useState<{t:string;v:number;desc:string}[]>([{t:'Hoje • 09:12',v:250000,desc:'Saldo inicial da simulação — carteira do jogador'},{t:'Hoje • 08:40',v:12000,desc:'Bônus de boas-vindas • Cidade Crypy'}]);
 const [district,setDistrict]=useState(0); const [size,setSize]=useState(250); const [rarity,setRarity]=useState(1); const [owned,setOwned]=useState<Lot[]>([]);
 const [msg,setMsg]=useState(''); const [prof,setProf]=useState(0); const [level,setLevel]=useState(3); const [hours,setHours]=useState(30);
 const [saves,setSaves]=useState<SaveRec[]>([]); const [saveMsg,setSaveMsg]=useState(''); const [saving,setSaving]=useState(false); const [marketFilter,setMarketFilter]=useState('Todos');
 const [checks,setChecks]=useState<Record<string,boolean>>({}); const [navNote,setNavNote]=useState('');
 const [rarityFilter,setRarityFilter]=useState('Todas'); const [wallet,setWallet]=useState(false); const [bidMsg,setBidMsg]=useState('');
 const main=FLAT[flat].main; const sub=FLAT[flat].sub;
 const landPrice=Math.round(DISTRICTS[district].price*size*RARITIES[rarity].mult);
 const salary=Math.round(PROFESSIONS[prof].salary*(1+(level-1)*0.18)*(hours/40));
 const goFlat=(n:number)=>{if(n<0||n>92)return; if(n===flat){setNavNote(`Você já está aqui: ${FLAT[n].title}.`);setOpen(false);return} setNavNote('');setFlat(n);setExpanded(FLAT[n].main);setOpen(false);window.scrollTo({top:0,behavior:'smooth'})};
 const handleMainClick=(mi:number)=>{if(mi===main){setExpanded(expanded===mi?-1:mi);setOpen(false);return} goMain(mi)};
 const goMain=(n:number)=>goFlat(n*3);
 const filteredFlat=FLAT.map((f,i)=>({...f,i})).filter(x=>(x.title.toLowerCase().includes(search.toLowerCase())));
 const chainHash=useMemo(()=>pseudoHash(FLAT[flat].title),[flat]);
 async function reloadSaves(){try{const d:any=await api('records.list',{collection:'crypyverse-saves'});setSaves(d.records||[])}catch{}}
 useEffect(()=>{reloadSaves()},[]);
 async function saveGame(){setSaving(true);setSaveMsg('');const value={balance,owned,statement,district,prof,level,savedAt:new Date().toISOString()};try{await api('records.create',{collection:'crypyverse-saves',value,idempotency_key:`crypy-${Date.now()}-${Math.random().toString(36).slice(2,8)}`});await reloadSaves();setSaveMsg('Simulação salva com sucesso.')}catch(e:any){setSaveMsg(e.message||'Não foi possível salvar agora.')}setSaving(false)}
 function loadSave(s:SaveRec){const v=s.value||{};setBalance(v.balance??250000);setOwned(v.owned||[]);setStatement(v.statement||[]);setSaveMsg('Save carregado na sua sessão atual.')}
 async function deleteSave(id:string){try{await api('records.delete',{collection:'crypyverse-saves',id});await reloadSaves();setSaveMsg('Save removido.')}catch(e:any){setSaveMsg(e.message)}}
 const bankAction=(type:'deposit'|'withdraw'|'transfer')=>{const v=Number(amount);if(!v||v<=0){setMsg('Digite um valor maior que zero.');return}if(type!=='deposit'&&v>balance){setMsg('Saldo insuficiente na simulação.');return}const nv=type==='deposit'?balance+v:balance-v;setBalance(nv);const label=type==='deposit'?'Depósito no Banco Crypy':type==='withdraw'?'Saque no caixa eletrônico':`Transferência para ${transferTo}`;setStatement(s=>[{t:'Agora',v:type==='deposit'?v:-v,desc:label},...s]);setMsg(type==='deposit'?'Depósito simulado confirmado.':type==='withdraw'?'Saque simulado liberado.':`Transferência simulada enviada para ${transferTo}. Nenhum valor real foi movido.`)};
 const buyLand=()=>{if(landPrice>balance){setMsg('Saldo insuficiente para esse lote. Reduza o tamanho ou a raridade.');return}const code=`CRYPY-${DISTRICTS[district].name.slice(0,3).toUpperCase()}-${Math.floor(1000+Math.random()*9000)}-${RARITIES[rarity].name.slice(0,2).toUpperCase()}`;const lot:Lot={id:String(Date.now()),district:DISTRICTS[district].name,size,rarity:RARITIES[rarity].name,price:landPrice,code};setOwned(o=>[lot,...o]);setBalance(b=>b-landPrice);setStatement(s=>[{t:'Agora',v:-landPrice,desc:`Compra de NFT • ${lot.code} • ${lot.district}`},...s]);setMsg(`Terreno comprado! NFT ${code} adicionado à sua coleção simulada.`)};
 const makeBid=(label:string)=> setBidMsg(`Lance simulado enviado para ${label}. O vendedor tem 24h de jogo para responder. Nenhum valor real foi movido.`);
 const nftGrid = (items:{d:typeof DISTRICTS[number];r:number;sz:number;owner:string;delta:string}[]) => <div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">{items.map((it,i)=>{const price=Math.round(it.d.price*it.sz*RARITIES[it.r].mult);return <article key={i} className="nft-card"><NftVisual d={it.d} rIdx={it.r} size={it.sz}/><div className="p-4"><div className="flex items-start justify-between gap-2"><div><div className="font-display font-black text-[15px] leading-tight [overflow-wrap:anywhere]">{it.d.name} • Lote #{String(1001+i*17).padStart(4,'0')}</div><div className="text-xs text-[var(--muted)] mt-1">Coleção Crypyverse • Dono: {it.owner}</div></div><span className={`text-xs font-black ${it.delta.startsWith('+')?'text-emerald-300':'text-rose-300'}`}>{it.delta}</span></div><div className="flex items-end justify-between mt-4"><div><div className="text-[10px] tracking-widest text-[var(--muted)]">PREÇO • CMG</div><div className="font-display font-black text-lg text-cyan-300">{fmtCMG(price)}</div></div><span className="text-xs text-[var(--muted)]">{it.sz} m²</span></div><div className="grid grid-cols-2 gap-2 mt-4"><button className="btn btn-primary !py-2.5 !px-2 text-[13px]" onClick={()=>{setDistrict(DISTRICTS.indexOf(it.d));setSize(it.sz);setRarity(it.r);goMain(4)}}>Comprar</button><button className="btn btn-ghost !py-2.5 !px-2 text-[13px]" onClick={()=>makeBid(`${it.d.name} #${1001+i*17}`)}><Gavel size={14}/> Lance</button></div><button className="btn btn-dark w-full mt-2 !py-2 text-[12px]" onClick={()=>goMain(2)}><MapPin size={13}/> Ver no Mapa</button></div></article>})}</div>;
 const showcaseItems = DISTRICTS.map((d,i)=>({d,r:(i%5),sz:[250,100,500,250,1000,250,100][i],owner:d.owner,delta:i%2?'+12,4%':'+8,2%'})).filter(x=>rarityFilter==='Todas'||RARITIES[x.r].name===rarityFilter);
 const marketItems = DISTRICTS.filter(d=>marketFilter==='Todos'||d.name===marketFilter).flatMap((d,i)=>[0,1,2].map(r=>({d,r:r+1,sz:120+i*40+r*60,owner:'Jogador verificado',delta:r===0?'+6,1%':r===1?'-2,4%':'+18,9%'}))).filter(x=>rarityFilter==='Todas'||RARITIES[x.r].name===rarityFilter);

 const overview=()=>{
  if(main===0) return <Section kicker="CAPÍTULO 01 • 1/3 VISÃO GERAL • COLEÇÃO EM DESTAQUE" title="Bem-vindo à Cidade Crypy." sub="Um NFT game de vida, negócios e cidade viva. Compre terrenos, construa, trabalhe, faça amigos e viva de renda — tudo em CMG, a moeda oficial do jogo. Este documento é o mapa completo do game: 31 capítulos × 3 subpáginas = 93 páginas, sem promessa de mintagem real.">
   <div className="rounded-[26px] overflow-hidden border border-[#3b2f7a] relative"><div className="p-5 sm:p-7" style={{background:'linear-gradient(120deg,#2b1660,#071a2a 55%,#05281f)'}}><span className="chip !bg-black/50 !text-white"><Flame size={13}/> DROP EM DESTAQUE • COLEÇÃO CRYPYVERSE</span><h3 className="font-display text-[clamp(1.5rem,5vw,2.6rem)] font-black leading-tight mt-4">Terrenos que são <span className="neon-text">NFTs vivos.</span><br/>A cidade é sua.</h3><p className="text-white/75 max-w-[620px] mt-3 text-[15px]">Cada lote tem código, raridade e história. Explore a vitrine, compare distritos e comece pelo lote que combina com o seu jogo.</p><div className="flex flex-wrap gap-2 mt-5"><button className="btn btn-primary" onClick={()=>goMain(7)}>Explorar marketplace <ArrowRight size={17}/></button><button className="btn btn-ghost !text-white !border-white/30" onClick={()=>goMain(4)}>Simular compra</button><button className="btn btn-dark" onClick={()=>goMain(2)}><MapPin size={16}/> Ver no Mapa</button></div></div><CityArt/></div>
   <div className="flex flex-wrap items-center justify-between gap-3"><div><H3>Vitrine NFT — em alta</H3><p className="text-sm text-[var(--muted)]">Filtre pela sidebar: {rarityFilter==='Todas'?'todas as raridades':'somente '+rarityFilter}.</p></div><span className="chip"><Layers size={13}/> {showcaseItems.length} NFTs em destaque</span></div>
   {nftGrid(showcaseItems)}
   {(bidMsg||msg)&&<div className="p-4 rounded-2xl bg-emerald-400/10 border border-emerald-300/30 text-sm">{bidMsg||msg}</div>}
   <div className="grid sm:grid-cols-3 gap-3"><div className="card p-5"><div className="text-xs text-[var(--muted)]">SUPPLY TOTAL CUNHADO</div><div className="font-display text-2xl font-black mt-1">1 quatrilhão</div><p className="text-sm text-[var(--muted)] mt-2">1.000.000.000.000.000 CMG depositados no Banco Central. Valores simulados para design.</p></div><div className="card p-5"><div className="text-xs text-[var(--muted)]">O QUE VOCÊ FAZ AQUI</div><div className="font-display text-2xl font-black mt-1">Viver + ganhar</div><p className="text-sm text-[var(--muted)] mt-2">Terreno, profissão, loja, festa, obra e óculos RA. A cidade responde às suas escolhas.</p></div><div className="card p-5"><div className="text-xs text-[var(--muted)]">MODO RA</div><div className="font-display text-2xl font-black mt-1">Na rua real</div><p className="text-sm text-[var(--muted)] mt-2">Aponte os óculos para um lote vazio e veja o terreno à venda flutuando na calçada.</p></div></div>
   <div className="card p-5"><H3>Comece por aqui — em 3 passos</H3><div className="grid sm:grid-cols-3 gap-3 mt-4">{[['1 • Crie seu avatar','Escolha visual, bairro inicial e sua primeira profissão. Sem pressa: dá pra trocar depois.'],['2 • Compre ou alugue','Use o simulador do capítulo 5 e 8 para sentir o preço antes de gastar 1 CMG.'],['3 • Viva a cidade','Trabalhe, construa, receba amigos e participe do evento da semana.']].map(([a,b])=><div key={a} className="p-4 rounded-xl bg-[var(--surface2)]"><b>{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div><button className="btn btn-primary mt-5" onClick={()=>goMain(1)}>Começar pela Lore <ArrowRight size={17}/></button></div>
   <div className="rounded-2xl border border-amber-300/30 bg-amber-400/10 p-4 text-sm"><b>⚠ Aviso importante:</b> protótipo e documento de design com blockchain simulada. Nenhuma moeda, terreno ou NFT aqui é um ativo real, e não há mintagem em blockchain mainnet.</div></Section>;
  if(main===1) return <Section kicker="CAPÍTULO 02 • VISÃO GERAL" title="A cidade que acordou com você." sub="Crypy nasceu de um blackout criativo: quando a rede antiga caiu, artistas, engenheiros e moradores reconstruíram a cidade em camadas — concreto, neon e dados. Hoje ela é viva: cada bairro tem humor, horário de pico e história."><div className="grid md:grid-cols-2 gap-4"><div className="card p-5"><H3>2051 • O ano zero</H3><P>Depois da Grande Reconexão, a prefeitura digital abriu o mapa para todo mundo. Quem chegava ganhava um lote, um avatar e uma chance. Quem ficava, construía a cidade junto.</P><p className="mt-3 text-sm">“Aqui ninguém é NPC. Todo prédio tem dono, toda festa tem história.” — mural do Centro</p></div><div className="card p-5"><H3>As três forças</H3><ul className="mt-3 space-y-2 text-sm text-[var(--muted)]"><li><b className="text-[var(--text)]">• Os Construtores:</b> levantam casas, lojas e pontes.</li><li><b className="text-[var(--text)]">• Os Comerciantes:</b> movem CMG, aluguel e feiras.</li><li><b className="text-[var(--text)]">• Os Artistas:</b> dão cor, som e festa para cada rua.</li></ul></div></div><div className="card p-5"><H3>Linha do tempo</H3><div className="grid sm:grid-cols-4 gap-3 mt-4">{[['2048','A rede cai'],['2051','Crypy é fundada'],['2054','Óculos RA chegam'],['2057','Você chega. A cidade muda.']].map(([y,t])=><div key={y}><div className="font-display font-black text-cyan-300">{y}</div><p className="text-sm text-[var(--muted)]">{t}</p></div>)}</div></div></Section>;
  if(main===2) return <Section kicker="CAPÍTULO 03 • VISÃO GERAL" title="Sete distritos, sete jeitos de viver." sub="O mapa é uma lista viva de bairros, não um desenho estático. Toque em um distrito para ver preço, clima e quem vive ali. A cidade cabe no seu bolso — e no seu óculos RA."><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">{DISTRICTS.map((d,i)=><article key={d.name} className="nft-card"><NftVisual d={d} rIdx={1} size={250}/><div className="p-4"><div className="flex justify-between gap-2"><b>{d.name}</b><span className="text-cyan-300 font-bold">{fmtCMG(d.price)}/m²</span></div><p className="text-sm text-[var(--muted)] mt-2">{d.desc}</p><div className="flex gap-2 mt-3"><button className="btn btn-primary flex-1 !py-2.5 !px-2 text-[13px]" onClick={()=>{setDistrict(i);goMain(4)}}>Comprar</button><button className="btn btn-ghost flex-1 !py-2.5 !px-2 text-[13px]" onClick={()=>{setDistrict(i);goMain(4)}}><MapPin size={14}/> Ver no Mapa</button></div></div></article>)}</div></Section>;
  if(main===3) return <Section kicker="CAPÍTULO 04 • VISÃO GERAL" title="Cada lote é único. E é seu." sub="O terreno é um NFT de design: tem código, distrito, tamanho, raridade e histórico. Raridade não é só brilho — ela muda preço, bônus de construção e visibilidade no mapa."><div className="grid sm:grid-cols-2 lg:grid-cols-3 gap-4">{RARITIES.map((r,i)=><article key={r.name} className="nft-card"><div className="h-[130px] relative flex items-center justify-center" style={{background:`linear-gradient(135deg, ${r.color}55, #0b0b1e)`}}><span className="text-6xl">💎</span><span className="absolute left-3 top-3"><RarityBadge name={r.name}/></span><span className="absolute right-3 top-3 chip !bg-black/50 !text-white">Chance {r.chance}</span></div><div className="p-4"><div className="flex justify-between"><b className="font-display">{r.name}</b><b className="text-cyan-300">×{r.mult}</b></div><p className="text-sm text-[var(--muted)] mt-2">{r.price}</p><p className="text-sm mt-2">{r.name==='Mítico'?'Lote com vista + evento próprio':r.name==='Lendário'?'Construção 2× mais rápida':'Decoração exclusiva'}</p><button className="btn btn-primary w-full mt-3 !py-2.5" onClick={()=>{setRarity(i);goMain(4)}}>Simular {r.name}</button></div></article>)}</div><div className="grid sm:grid-cols-3 gap-3">{[['Pequeno • 100 m²','Casa, estúdio, lojinha. O primeiro passo.'],['Médio • 250 m²','Casa + quintal, loja com estoque, café.'],['Grande • 1.000 m²','Prédio, praça privada, evento e renda.']].map(([a,b])=><div key={a} className="card p-4"><b>{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div></Section>;
  if(main===4) return <Section kicker="CAPÍTULO 05 • VISÃO GERAL" title="Simulador de compra de terreno." sub="Escolha distrito, tamanho e raridade. O preço aparece na hora, o NFT é gerado e a compra entra no seu extrato simulado. Nada aqui move dinheiro real."><div className="grid lg:grid-cols-[1.2fr_.8fr] gap-4"><div className="card p-5 space-y-4"><label className="block text-sm font-bold">Distrito<select className="select mt-1" value={district} onChange={e=>setDistrict(Number(e.target.value))}>{DISTRICTS.map((d,i)=><option key={d.name} value={i}>{d.name} — {fmtCMG(d.price)}/m²</option>)}</select></label><label className="block text-sm font-bold">Tamanho do lote<select className="select mt-1" value={size} onChange={e=>setSize(Number(e.target.value))}>{[100,250,500,1000].map(s=><option key={s} value={s}>{s} m²</option>)}</select></label><label className="block text-sm font-bold">Raridade<select className="select mt-1" value={rarity} onChange={e=>setRarity(Number(e.target.value))}>{RARITIES.map((r,i)=><option key={r.name} value={i}>{r.name} — ×{r.mult}</option>)}</select></label><div className="p-4 rounded-xl bg-[var(--surface2)] flex justify-between"><span>Preço total</span><b className="text-emerald-300 text-xl">{fmtCMG(landPrice)}</b></div><div className="p-4 rounded-xl bg-[var(--surface2)] flex justify-between"><span>Seu saldo simulado</span><b>{fmtCMG(balance)}</b></div><button className="btn btn-primary w-full" onClick={buyLand}>Comprar terreno simulado</button>{msg&&<div className="p-3 rounded-xl bg-emerald-400/10 border border-emerald-300/30 text-sm">{msg}</div>}</div><div className="nft-card"><NftVisual d={DISTRICTS[district]} rIdx={rarity} size={size}/><div className="p-4"><div className="text-xs tracking-widest text-[var(--muted)]">NFT GERADO • PRÉVIA</div><div className="font-display font-black mt-2">{DISTRICTS[district].name} • {size} m²</div><p className="text-sm text-[var(--muted)] mt-1">Raridade: <b style={{color:RARITIES[rarity].color}}>{RARITIES[rarity].name}</b> • Dono: você</p><p className="mono text-xs mt-3 break-all">ID: CRYPY-{DISTRICTS[district].name.slice(0,3).toUpperCase()}-{size}-{RARITIES[rarity].name.toUpperCase()}</p></div></div><div className="mt-4 card p-5"><b>Seus lotes ({owned.length})</b>{owned.length===0?<p className="text-sm text-[var(--muted)] mt-2">Nenhum lote ainda. Faça sua primeira simulação ao lado.</p>:owned.map(l=><div key={l.id} className="mt-2 p-3 rounded-xl bg-[var(--surface2)] text-sm flex justify-between gap-2"><span><b>{l.code}</b><br/>{l.district} • {l.size} m² • {l.rarity}</span><b>{fmtCMG(l.price)}</b></div>)}</div></div></Section>;
  if(main===5) return <Section kicker="CAPÍTULO 06 • VISÃO GERAL" title="Vender bem é um jogo dentro do jogo." sub="Preço, foto, história e timing. Um lote perto de evento vende mais. Um lote abandonado perde visibilidade. O sistema sugere preço — você decide."><div className="grid md:grid-cols-3 gap-3">{[['1 • Anuncie','Fotos em RA, descrição honesta e preço com base no distrito + raridade.'],['2 • Negocie','Propostas chegam na carteira. Aceite, recuse ou faça contraproposta.'],['3 • Transfira','Contrato simulado, taxa transparente e NFT muda de dono na hora.']].map(([a,b])=><div key={a} className="card p-5"><b>{a}</b><p className="text-sm text-[var(--muted)] mt-2">{b}</p></div>)}</div><div className="card p-5"><H3>Seus lotes à venda — simulação</H3>{owned.length===0?<P>Nenhum lote comprado ainda. Volte para o capítulo 5, compre um lote simulado e ele aparecerá aqui para revenda.</P>:owned.map(l=><div key={l.id} className="flex flex-wrap justify-between gap-3 mt-3 p-3 rounded-xl bg-[var(--surface2)]"><span><b>{l.code}</b> • {l.district} • {l.rarity}<br/><span className="text-sm text-[var(--muted)]">Preço sugerido de revenda: {fmtCMG(l.price*1.18)} • Variação +18%</span></span><button className="btn btn-primary" onClick={()=>{setBalance(b=>b+Math.round(l.price*1.18));setOwned(o=>o.filter(x=>x.id!==l.id));setStatement(s=>[{t:'Agora',v:Math.round(l.price*1.18),desc:`Venda de NFT • ${l.code}`},...s]);setMsg(`Lote ${l.code} vendido por ${fmtCMG(l.price*1.18)} (simulado).`)}}>Vender por {fmtCMG(l.price*1.18)}</button></div>)} {msg&&<div className="mt-4 p-3 rounded-xl bg-emerald-400/10 text-sm">{msg}</div>}</div></Section>;
  if(main===6) return <Section kicker="CAPÍTULO 07 • VISÃO GERAL" title="Do lote vazio à casa com sua cara." sub="Construir é em etapas, com custo, tempo e escolhas visíveis. Você pode construir sozinho, contratar um engenheiro ou comprar um projeto pronto."><div className="grid md:grid-cols-2 gap-4"><div className="card p-5"><H3>Etapas da obra</H3><ol className="mt-3 space-y-3 text-sm text-[var(--muted)]"><li><b className="text-[var(--text)]">1. Terreno limpo:</b> 2 dias de jogo • 1.200 CMG</li><li><b className="text-[var(--text)]">2. Estrutura:</b> 5 dias • 18.000 CMG</li><li><b className="text-[var(--text)]">3. Acabamento:</b> 4 dias • 24.000 CMG</li><li><b className="text-[var(--text)]">4. Decoração RA:</b> instantâneo • a partir de 800 CMG</li></ol></div><div className="card p-5"><H3>Estilos prontos</H3><div className="grid grid-cols-2 gap-2 mt-3">{['Minimal Neon','Casa Praia','Loft Cyber','Mansão Luxo'].map(s=><div key={s} className="p-3 rounded-xl bg-[var(--surface2)] text-sm font-bold">{s}</div>)}</div><p className="text-sm text-[var(--muted)] mt-3">Cada estilo muda luz, som ambiente e como os visitantes veem sua casa em RA.</p></div></div></Section>;
  if(main===7) return <Section kicker="CAPÍTULO 08 • VISÃO GERAL • MARKETPLACE NFT" title="A feira da cidade, aberta 24h." sub="Filtre por distrito e raridade na sidebar. Os preços abaixo são ofertas simuladas do documento — o mercado real do jogo reage a eventos, estações e demanda."><div className="flex flex-wrap gap-2">{['Todos',...DISTRICTS.map(d=>d.name)].map(f=><button key={f} onClick={()=>setMarketFilter(f)} className={`chip ${marketFilter===f?'!bg-cyan-300 !text-black font-bold':''}`}>{f}</button>)}</div>{nftGrid(marketItems)}{marketItems.length===0&&<div className="card p-6 text-center">Nenhum NFT com esse filtro. Escolha outra raridade na sidebar.</div>}{(msg||bidMsg)&&<div className="p-3 rounded-xl bg-emerald-400/10 text-sm">{bidMsg||msg}</div>}</Section>;
  if(main===8) return <Section kicker="CAPÍTULO 09 • VISÃO GERAL" title="1 quatrilhão de CMG. Com destino claro." sub="O supply total foi cunhado uma única vez no documento de design e depositado no Banco Central. A partir daí, o jogo distribui por regras — não por improviso."><div className="grid md:grid-cols-2 gap-4"><div className="card p-6 text-center"><div className="text-xs tracking-widest text-[var(--muted)]">SUPPLY TOTAL • BANCO CENTRAL</div><div className="font-display text-[clamp(1.4rem,5vw,2.6rem)] font-black neon-text mt-2 break-all">1.000.000.000.000.000</div><div className="font-display text-xl mt-1">CMG</div><p className="text-sm text-[var(--muted)] mt-3">Simulação de design. Não é oferta, investimento ou ativo real.</p></div><div className="card p-5"><H3>Distribuição planejada</H3>{[['Recompensas de jogo',38,'#00ff88'],['Banco e liquidez',24,'#00e5ff'],['Eventos e temporadas',14,'#ffd166'],['Desenvolvimento',12,'#a06bff'],['Comunidade e DAO',8,'#ff4fd8'],['Reserva de segurança',4,'#9fc8bb']].map(([a,v,c])=><div key={a as string} className="mt-3"><div className="flex justify-between text-sm"><span>{a}</span><b>{v}%</b></div><div className="progress mt-1"><div style={{width:`${v}%`,background:c as string}}/></div></div>)}</div></div><div className="card p-5"><H3>Como o CMG circula</H3><ul className="mt-2 space-y-2 text-sm text-[var(--muted)]"><li>• Jogador trabalha → recebe salário em CMG</li><li>• Jogador compra terreno/loja → CMG vai para vendedor</li><li>• Lojas pagam aluguel e impostos → CMG volta para a cidade</li><li>• Cidade paga eventos e serviços → CMG volta para os jogadores</li></ul></div></Section>;
  if(main===9) return <Section kicker="CAPÍTULO 10 • VISÃO GERAL • COFRE NFT" title="Banco Central + sua conta. Sem letra miúda." sub="O Banco Crypy guarda o supply total e oferece conta, depósito, saque e transferência simulados. Use o simulador abaixo para sentir o fluxo — e salve para continuar depois."><div className="grid md:grid-cols-2 gap-4"><div className="rounded-[22px] p-5 border border-[#8b5cf6] relative overflow-hidden" style={{background:'linear-gradient(135deg,#2a1660,#0b0b1e)'}}><div className="flex items-center gap-2 text-sm"><Landmark size={18}/> BANCO CENTRAL • COFRE NFT</div><div className="font-display text-[clamp(1.3rem,5vw,2rem)] font-black mt-2 break-all neon-text">{fmtCMG(QUADRILHAO)}</div><p className="text-sm text-white/70 mt-1">Saldo de design, travado para distribuição por regras do jogo.</p><div className="flex gap-2 mt-4">{['38% Recompensas','24% Banco','14% Eventos'].map(x=><span key={x} className="chip !bg-black/40 !text-white text-[11px]">{x}</span>)}</div></div><div className="card p-5"><div className="flex items-center gap-2 text-sm"><Wallet size={18}/> SUA CARTEIRA SIMULADA</div><div className="font-display text-2xl font-black mt-2 text-emerald-300">{fmtCMG(balance)}</div><p className="text-sm text-[var(--muted)] mt-1">{owned.length} lote(s) • {statement.length} movimentos</p><div className="progress mt-4"><div style={{width:'62%'}}/></div><p className="text-xs text-[var(--muted)] mt-2">Cofre do jogador • 62% da meta mensal</p></div></div><div className="card p-5"><div className="grid sm:grid-cols-3 gap-3"><label className="block text-sm font-bold">Valor (CMG)<input className="input mt-1" value={amount} onChange={e=>setAmount(e.target.value)} inputMode="numeric"/></label><label className="block text-sm font-bold">Transferir para<select className="select mt-1" value={transferTo} onChange={e=>setTransferTo(e.target.value)}><option>Luna • Residencial</option><option>Kaio • Cyberpunk</option><option>Maya • Praia</option><option>Loja do Bairro • Comercial</option></select></label><div className="flex items-end"><button className="btn btn-primary w-full" onClick={saveGame} disabled={saving}>{saving?'Salvando…':'Salvar simulação'}</button></div></div><div className="flex flex-wrap gap-2 mt-4"><button className="btn btn-primary" onClick={()=>bankAction('deposit')}>Depositar</button><button className="btn btn-cyan" onClick={()=>bankAction('withdraw')}>Sacar</button><button className="btn btn-ghost" onClick={()=>bankAction('transfer')}>Transferir</button></div>{msg&&<div className="mt-3 p-3 rounded-xl bg-emerald-400/10 text-sm">{msg}</div>}{saveMsg&&<div className="mt-2 text-sm text-[var(--muted)]">{saveMsg}</div>}</div><div className="card p-5"><H3>Empréstimo simulado</H3><p className="text-sm text-[var(--muted)] mt-2">Até 40% do valor dos seus lotes, com juros de 1,2% ao mês de jogo e parcelas claras. Sem taxa escondida, sem pegadinha.</p><div className="grid sm:grid-cols-3 gap-2 mt-3 text-sm"><div className="p-3 rounded-xl bg-[var(--surface2)]">Limite<br/><b>{fmtCMG(owned.reduce((a,l)=>a+l.price,0)*0.4||100000)}</b></div><div className="p-3 rounded-xl bg-[var(--surface2)]">Juros<br/><b>1,2% / mês</b></div><div className="p-3 rounded-xl bg-[var(--surface2)]">Prazo<br/><b>Até 12 meses</b></div></div></div></Section>;
  if(main===10) return <Section kicker="CAPÍTULO 11 • VISÃO GERAL" title="Juros, cofre e extrato que você entende." sub="O cofre rende, o extrato explica e o empréstimo mostra o custo total antes de você aceitar. Transparência é parte do design."><div className="grid md:grid-cols-3 gap-3">{[['Conta Corrente','0,4% / mês • saque livre'],['Cofre Poupança','1,1% / mês • rende todo dia'],['Cofre Trancado','1,8% / mês • 30 dias sem tocar']].map(([a,b])=><div key={a} className="card p-5"><b>{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div><div className="card p-5"><H3>Extrato simulado</H3><div className="mt-3 divide-y divide-[var(--line)]">{statement.map((s,i)=><div key={i} className="py-3 flex justify-between gap-3"><span><b>{s.desc}</b><br/><span className="text-xs text-[var(--muted)]">{s.t}</span></span><b className={s.v>=0?'text-emerald-300':'text-rose-300'}>{s.v>=0?'+':''}{fmtCMG(s.v)}</b></div>)}</div></div></Section>;
  if(main===11) return <Section kicker="CAPÍTULO 12 • VISÃO GERAL" title="Sua carteira, seus NFTs, seu histórico." sub="A carteira guarda CMG, terrenos, roupas, móveis e conquistas. Cada item tem código, origem e histórico — como um documento do seu personagem."><div className="grid md:grid-cols-2 gap-4"><div className="card p-5"><H3>Resumo</H3><div className="mt-3 space-y-2 text-sm"><div className="flex justify-between"><span>CMG disponível</span><b>{fmtCMG(balance)}</b></div><div className="flex justify-between"><span>Terrenos NFT</span><b>{owned.length}</b></div><div className="flex justify-between"><span>Valor em terrenos</span><b>{fmtCMG(owned.reduce((a,l)=>a+l.price,0))}</b></div><div className="flex justify-between"><span>Patrimônio simulado</span><b className="text-emerald-300">{fmtCMG(balance+owned.reduce((a,l)=>a+l.price,0))}</b></div></div></div><div className="card p-5"><H3>Segurança da carteira</H3><ul className="mt-3 space-y-2 text-sm text-[var(--muted)]"><li>• Confirmação em duas etapas para transferências grandes</li><li>• Histórico imutável no protótipo: nada some sem registro</li><li>• Alerta se um anúncio copiar o nome de uma loja real do jogo</li></ul></div></div><div className="card p-5"><H3>Seus NFTs</H3>{owned.length===0?<P>Nenhum NFT ainda. Compre no capítulo 5 e ele aparece aqui.</P>:<div className="grid sm:grid-cols-2 gap-3 mt-3">{owned.map(l=><div key={l.id} className="nft-card"><div className="p-4"><RarityBadge name={l.rarity}/><div className="font-display font-black mt-2">{l.code}</div><p className="text-sm text-[var(--muted)]">{l.district} • {l.size} m²</p><div className="flex justify-between mt-3"><b className="text-cyan-300">{fmtCMG(l.price)}</b><span className="text-emerald-300 text-xs font-bold">+18% sugerido</span></div></div></div>)}</div>}</div><div className="card p-5"><H3>Saves salvos</H3>{saves.length===0?<P>Nenhum save ainda. Salve sua simulação no Banco Crypy (capítulo 10) e ela aparecerá aqui.</P>:saves.map(s=><div key={s.id} className="flex flex-wrap justify-between gap-2 mt-2 p-3 rounded-xl bg-[var(--surface2)] text-sm"><span>Save • {fmtCMG(s.value?.balance||0)} • {(s.value?.owned||[]).length} lote(s)</span><span className="flex gap-2"><button className="btn btn-ghost !py-2" onClick={()=>loadSave(s)}>Carregar</button><button className="btn btn-ghost !py-2" onClick={()=>deleteSave(s.id)}><Trash2 size={15}/></button></span></div>)}</div></Section>;
  if(main===12) return <Section kicker="CAPÍTULO 13 • VISÃO GERAL" title="Trabalhar no jogo é jogar de outro jeito." sub="São 20 profissões com salário, requisitos e XP. Você pode ter uma profissão principal e bicos — e trocar de carreira sem perder seu patrimônio."><div className="grid sm:grid-cols-3 gap-3"><div className="card p-5"><b className="font-display text-3xl">20</b><p className="text-sm text-[var(--muted)]">profissões no lançamento</p></div><div className="card p-5"><b className="font-display text-3xl">4</b><p className="text-sm text-[var(--muted)]">áreas: Comércio, Serviços, Pública e Urbana</p></div><div className="card p-5"><b className="font-display text-3xl">Nível 15</b><p className="text-sm text-[var(--muted)]">para disputar cargos eleitos</p></div></div><div className="grid sm:grid-cols-2 gap-4">{PROFESSIONS.slice(0,6).map((p,i)=><article key={p.name} className="nft-card p-4"><div className="flex gap-3"><span className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[#8b5cf6] to-[#00e5ff] flex items-center justify-center text-3xl shrink-0">{p.emoji}</span><div><b>{p.name}</b><div className="flex gap-2 mt-1"><span className="chip !py-1">{p.cat}</span><span className="chip !py-1">Nível {3+i}</span></div></div></div><p className="text-sm text-[var(--muted)] mt-3">{p.req} • {p.xp}</p><div className="flex justify-between mt-3"><span className="text-sm">Salário</span><b className="text-emerald-300">{fmtCMG(p.salary)}/mês</b></div></article>)}</div></Section>;
  if(main===13) return <Section kicker="CAPÍTULO 14 • VISÃO GERAL" title="Quem vende, serve e faz a cidade girar." sub="Corretores, lojistas, chefs, designers, streamers, mecânicos e mais. Aqui o salário cresce com reputação — cliente feliz volta e indica."><div className="grid md:grid-cols-2 gap-4">{PROFESSIONS.filter(p=>['Comércio','Serviços'].includes(p.cat)).map(p=><article key={p.name} className="nft-card p-4"><div className="flex gap-3"><span className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[#00e5ff] to-[#00ff88] flex items-center justify-center text-3xl shrink-0">{p.emoji}</span><div className="min-w-0"><b className="[overflow-wrap:anywhere]">{p.name}</b><div className="mt-1"><span className="chip !py-1">{p.cat}</span></div></div></div><p className="text-sm text-[var(--muted)] mt-3">{p.req}</p><div className="flex justify-between mt-2 text-sm"><span>{p.xp}</span><b className="text-emerald-300">{fmtCMG(p.salary)}/mês</b></div></article>)}</div></Section>;
  if(main===14) return <Section kicker="CAPÍTULO 15 • VISÃO GERAL" title="Quem cuida da cidade também vive dela." sub="Polícia, bombeiros, médicos, professores, engenheiros e cargos eleitos. Profissões públicas têm estabilidade e impacto direto no mapa."><div className="grid md:grid-cols-2 gap-4">{PROFESSIONS.filter(p=>['Pública','Urbana'].includes(p.cat)).map(p=><article key={p.name} className="nft-card p-4"><div className="flex gap-3"><span className="w-14 h-14 rounded-2xl bg-gradient-to-br from-[#ff4fd8] to-[#ffd166] flex items-center justify-center text-3xl shrink-0">{p.emoji}</span><div className="min-w-0"><b className="[overflow-wrap:anywhere]">{p.name}</b><div className="mt-1"><span className="chip !py-1">{p.cat}</span></div></div></div><p className="text-sm text-[var(--muted)] mt-3">{p.req}</p><div className="flex justify-between mt-2 text-sm"><span>{p.xp}</span><b className="text-emerald-300">{fmtCMG(p.salary)}/mês</b></div></article>)}</div></Section>;
  if(main===15) return <Section kicker="CAPÍTULO 16 • VISÃO GERAL" title="Calculadora de salário por profissão." sub="Suba de nível, ganhe XP e veja o salário responder. A calculadora usa os valores-base do documento — o jogo real ajusta por desempenho e reputação."><div className="grid lg:grid-cols-[1fr_.9fr] gap-4"><div className="card p-5 space-y-4"><label className="block text-sm font-bold">Profissão<select className="select mt-1" value={prof} onChange={e=>setProf(Number(e.target.value))}>{PROFESSIONS.map((p,i)=><option key={p.name} value={i}>{p.name}</option>)}</select></label><label className="block text-sm font-bold">Nível de carreira: {level}<input type="range" min={1} max={15} className="w-full" value={level} onChange={e=>setLevel(Number(e.target.value))}/></label><label className="block text-sm font-bold">Horas por semana: {hours}<input type="range" min={10} max={50} step={5} className="w-full" value={hours} onChange={e=>setHours(Number(e.target.value))}/></label><div className="p-4 rounded-xl bg-[var(--surface2)]"><div className="text-sm text-[var(--muted)]">Salário mensal estimado</div><div className="font-display text-3xl font-black text-emerald-300">{fmtCMG(salary)}</div><p className="text-sm text-[var(--muted)] mt-1">{PROFESSIONS[prof].xp} • {PROFESSIONS[prof].req}</p></div></div><div className="card p-5"><H3>Trilha de promoção</H3>{[['Nível 1–4','Aprendiz • aprende a rotina'],['Nível 5–9','Profissional • ganha bônus'],['Nível 10–14','Especialista • lidera equipes'],['Nível 15','Mestre • pode disputar cargos eleitos']].map(([a,b])=><div key={a} className="mt-3 p-3 rounded-xl bg-[var(--surface2)]"><b>{a}</b><p className="text-sm text-[var(--muted)]">{b}</p></div>)}</div></div></Section>;
  if(main===16) return <Section kicker="CAPÍTULO 17 • VISÃO GERAL" title="Amigos, casas e festas que viram memória." sub="Visite, convide, cozinhe junto e monte sua festa. A casa não é só decoração — é onde a sua história no jogo acontece."><div className="grid md:grid-cols-3 gap-4">{[['Lista de amigos','Adicione, visite e ajude na obra do amigo.','👥'],['Casas abertas','Abra sua casa para visitas e ganhe reputação.','🏠'],['Festas','Monte playlist, convide e escolha o tema.','🎉']].map(([a,b,e])=><div key={a} className="nft-card p-5"><span className="text-4xl">{e}</span><b className="block mt-3">{a}</b><p className="text-sm text-[var(--muted)] mt-2">{b}</p></div>)}</div><div className="card p-5"><H3>Ideia de festa em 1 minuto</H3><p className="text-sm text-[var(--muted)] mt-2">Tema Neon Praia • 12 convidados • DJ da praça • Comida do chef do bairro • Foto em RA na varanda. Custo estimado: 8.400 CMG.</p></div></Section>;
  if(main===17) return <Section kicker="CAPÍTULO 18 • VISÃO GERAL" title="A cidade tem agenda — e você está nela." sub="Praças com shows, feiras, cinema ao ar livre e campeonatos. Eventos bons atraem visitantes, e visitantes gastam nas lojas do bairro."><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">{[['Sexta • 19h','Show na Praça Central','🎤'],['Sábado • 10h','Feira do Residencial','🧺'],['Sábado • 21h','Noite Cyberpunk','🌃'],['Domingo • 16h','Cinema no Parque','🎬']].map(([a,b,e])=><div key={b} className="nft-card p-4"><span className="text-4xl">{e}</span><span className="block text-xs text-cyan-300 font-bold mt-3">{a}</span><p className="font-bold mt-1">{b}</p></div>)}</div></Section>;
  if(main===18) return <Section kicker="CAPÍTULO 19 • VISÃO GERAL" title="Renda, aluguel e impostos — sem susto." sub="A economia é um ciclo. Você ganha, gasta, investe e paga impostos que voltam como praça limpa, show e segurança."><div className="overflow-x-auto card"><table className="w-full min-w-[560px] text-sm"><thead><tr className="text-left border-b border-[var(--line)]"><th className="p-3">Item</th><th className="p-3">Regra</th><th className="p-3">Exemplo</th></tr></thead><tbody>{[['Aluguel de loja','6% do faturamento ou valor fixo','Loja com 100 mil CMG → 6.000 CMG'],['Imposto da cidade','3% sobre vendas de terrenos','Venda de 500 mil CMG → 15.000 CMG'],['Manutenção da casa','0,5% do valor por mês','Casa de 400 mil CMG → 2.000 CMG'],['Taxa de evento','2% da bilheteria','Show com 50 mil CMG → 1.000 CMG']].map(r=><tr key={r[0]} className="border-b border-[var(--line)]"><td className="p-3 font-bold">{r[0]}</td><td className="p-3">{r[1]}</td><td className="p-3">{r[2]}</td></tr>)}</tbody></table></div><div className="card p-5"><H3>Orçamento saudável</H3><p className="text-sm text-[var(--muted)] mt-2">Sugestão do jogo: 50% para viver, 30% para investir, 20% para o cofre. O HUD mostra o alerta antes de você estourar o mês.</p></div></Section>;
  if(main===19) return <Section kicker="CAPÍTULO 20 • VISÃO GERAL" title="Sua loja, sua marca, sua fila." sub="Abra uma loja, monte vitrine, defina preço e atenda. Lojas com boa reputação aparecem primeiro no mapa e recebem mais visitantes."><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-4">{[['Café Neon','Praça • 42 clientes/dia'],['Loja de Roupas','Centro • 68 clientes/dia'],['Oficina Hover','Cyberpunk • 31 clientes/dia'],['Floraria do Parque','Parque • 25 clientes/dia']].map(([a,b])=><div key={a} className="nft-card p-4"><div className="h-[80px] rounded-xl bg-gradient-to-br from-[#8b5cf6] to-[#00e5ff] flex items-center justify-center text-3xl">🏪</div><b className="block mt-3">{a}</b><p className="text-sm text-[var(--muted)]">{b}</p><button className="btn btn-primary w-full mt-3 !py-2 text-[13px]" onClick={()=>goMain(7)}>Ver no marketplace</button></div>)}</div></Section>;
  if(main===20) return <Section kicker="CAPÍTULO 21 • VISÃO GERAL • ÓCULOS RA" title="A cidade na sua frente. Literalmente." sub="Os óculos Crypy RA projetam o jogo sobre a rua real: lotes à venda, nomes de lojas, eventos e amigos por perto. Sem óculos, você joga normal. Com eles, o mundo dobra."><div className="rounded-[26px] p-6 sm:p-8 border border-cyan-300/40 relative overflow-hidden" style={{background:'linear-gradient(120deg,#0a2a3a,#1a0f45)'}}><div className="flex flex-col md:flex-row gap-6 items-center"><div className="flex-1"><span className="chip !bg-black/50 !text-white"><Glasses size={13}/> MOCKUP RA • CRYPY GLASSES PRO</span><h3 className="font-display text-2xl sm:text-3xl font-black mt-3">Veja o NFT<br/><span className="neon-text">flutuando na rua.</span></h3><p className="text-white/75 mt-3 text-sm">Lote, preço, raridade e dono — direto na sua visão. Sem tirar o celular do bolso.</p><div className="flex flex-wrap gap-2 mt-4"><button className="btn btn-primary" onClick={()=>goMain(21)}>Comprar na rua real <ArrowRight size={16}/></button><button className="btn btn-ghost !text-white" onClick={()=>goMain(22)}>Decorar em RA</button></div></div><div className="w-full md:w-[280px] shrink-0"><div className="rounded-[44px] border-[10px] border-black bg-[#050508] p-4 text-center shadow-[0_0_45px_rgba(0,229,255,.35)]"><div className="text-[42px]">🥽</div><div className="font-display font-black">CRYPY RA PRO</div><p className="text-xs text-[var(--muted)] mt-1">46.000 CMG • Construção em escala real</p><div className="mt-3 p-2 rounded-xl bg-cyan-400/10 border border-cyan-300/30 text-xs">Lote à venda • Centro<br/><b>756.000 CMG • Raro</b></div></div></div></div></div><div className="grid md:grid-cols-3 gap-4">{[['Ver lotes','Preço e raridade flutuando no lote real','🏙️'],['Ver pessoas','Nome, profissão e status do amigo','👤'],['Ver eventos','Setas e portais até a festa','🎪']].map(([a,b,e])=><div key={a} className="nft-card p-5"><span className="text-4xl">{e}</span><b className="block mt-3">{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div><div className="rounded-2xl p-5 bg-cyan-400/10 border border-cyan-300/30"><b>Modo rua segura:</b> o jogo pausa alertas quando você atravessa ruas e reduz brilho à noite. Jogar bem também é jogar com cuidado.</div></Section>;
  if(main===21) return <Section kicker="CAPÍTULO 22 • VISÃO GERAL" title="Compre um terreno apontando para ele." sub="Na rua real, o lote vazio ganha contorno neon, preço e botão de compra. Você confirma no celular, o NFT vai para a carteira e a placa muda para “vendido”."><div className="card p-5"><div className="rounded-2xl overflow-hidden border border-[var(--line)]"><div className="h-[220px] relative bg-gradient-to-b from-sky-300/40 to-emerald-100/50"><div className="absolute left-[18%] top-[32%] w-[52%] h-[38%] border-[3px] border-dashed border-cyan-500 bg-cyan-300/20 rounded-xl flex items-center justify-center text-center text-sm font-bold text-cyan-900 p-2">LOTE À VENDA<br/>Centro • 250 m²<br/>Raro • 756.000 CMG</div><span className="absolute right-4 top-4 chip !bg-black text-white">RA • GPS ATIVO</span><span className="absolute bottom-3 left-3 text-xs bg-black/70 text-white px-2 py-1 rounded">Rua simulada • demonstração de interface</span></div></div><ol className="mt-4 space-y-2 text-sm text-[var(--muted)]"><li><b className="text-[var(--text)]">1. Aponte:</b> o lote ganha contorno e ficha completa.</li><li><b className="text-[var(--text)]">2. Compare:</b> veja lotes vizinhos e histórico de preço.</li><li><b className="text-[var(--text)]">3. Compre:</b> confirme, receba o NFT e visite seu lote no mapa.</li></ol><button className="btn btn-primary mt-4" onClick={()=>goMain(4)}>Comprar este lote no simulador</button></div></Section>;
  if(main===22) return <Section kicker="CAPÍTULO 23 • VISÃO GERAL" title="Decore antes de gastar 1 CMG." sub="Arraste sofá, planta, neon e parede na sua sala real. Quando gostar, salve o projeto e aplique no lote do jogo. O que você vê é o que vai existir."><div className="grid sm:grid-cols-3 gap-4">{[['Arrastar e soltar','Móveis em escala real','🛋️'],['Testar luz','Dia, noite e neon','💡'],['Salvar projeto','Aplica no lote em 1 toque','💾']].map(([a,b,e])=><div key={a} className="nft-card p-5"><span className="text-4xl">{e}</span><b className="block mt-3">{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div></Section>;
  if(main===23) return <Section kicker="CAPÍTULO 24 • VISÃO GERAL" title="Fome, energia e diversão — em equilíbrio." sub="O HUD mostra o que seu personagem precisa, sem virar cobrança. Cuide da rotina e ganhe bônus; ignore por muito tempo e o desempenho cai."><div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-3">{[['Energia',82,'#00ff88'],['Fome',64,'#ffd166'],['Diversão',71,'#ff4fd8'],['Social',88,'#00e5ff']].map(([a,v,c])=><div key={a as string} className="card p-4"><div className="flex justify-between"><b>{a}</b><span>{v}%</span></div><div className="progress mt-2"><div style={{width:`${v}%`,background:c as string}}/></div></div>)}</div><div className="card p-5"><H3>Rotina de um dia bom</H3><p className="text-sm text-[var(--muted)] mt-2">08h café no bairro → 09h trabalho → 13h almoço com amigo → 15h obra da casa → 19h evento na praça → 22h descanso com bônus de energia.</p></div></Section>;
  if(main===24) return <Section kicker="CAPÍTULO 25 • VISÃO GERAL" title="Seu avatar, do seu jeito." sub="Rosto, cabelo, roupa, acessório e aura. Roupas podem ser compradas, criadas ou ganhas em eventos — e algumas viram itens colecionáveis."><div className="grid sm:grid-cols-3 gap-4">{[['Visual base','20 rostos • 40 cabelos • tons e estilos','🧑'],['Roupas','Jaquetas neon, tênis, vestidos, uniformes','👕'],['Acessórios','Óculos RA, mochilas, pets digitais','🕶️']].map(([a,b,e])=><div key={a} className="nft-card p-5"><span className="text-4xl">{e}</span><b className="block mt-3">{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div></Section>;
  if(main===25) return <Section kicker="CAPÍTULO 26 • VISÃO GERAL" title="Toda semana tem um motivo para voltar." sub="Temporadas com tema, missões diárias e eventos de distrito. Complete, ganhe CMG e itens — e desbloqueie histórias que só acontecem uma vez."><div className="grid md:grid-cols-3 gap-4">{[['Temporada Neon','4 semanas • 40 recompensas','🌈'],['Missão diária','3 tarefas rápidas por dia','🎯'],['Evento de distrito','Torneio, feira e show','🎪']].map(([a,b,e])=><div key={a} className="nft-card p-5"><span className="text-4xl">{e}</span><b className="block mt-3">{a}</b><p className="text-sm text-[var(--muted)]">{b}</p></div>)}</div><div className="card p-5"><H3>Missões desta semana (exemplo)</H3><ul className="mt-2 space-y-2 text-sm text-[var(--muted)]"><li>• Visite 3 distritos e tire foto em RA — <b className="text-[var(--text)]">+2.500 CMG</b></li><li>• Ajude em uma obra de amigo — <b className="text-[var(--text)]">+180 XP</b></li><li>• Venda 1 item na sua loja — <b className="text-[var(--text)]">+1.200 CMG</b></li></ul></div></Section>;
  if(main===26) return <Section kicker="CAPÍTULO 27 • VISÃO GERAL" title="A cidade também é votada por você." sub="A DAO decide regras, eventos e taxas. Quem tem reputação e participa vota com mais peso — mas ninguém decide sozinho."><div className="grid md:grid-cols-2 gap-4"><div className="card p-5"><H3>Proposta em votação</H3><p className="text-sm text-[var(--muted)] mt-2">“Abrir feira noturna no Parque às sextas?”</p><div className="mt-4"><div className="flex justify-between text-sm"><span>Sim</span><b>68%</b></div><div className="progress mt-1"><div style={{width:'68%'}}/></div><div className="flex justify-between text-sm mt-3"><span>Não</span><b>32%</b></div><div className="progress mt-1"><div style={{width:'32%',background:'#ff4fd8'}}/></div></div></div><div className="card p-5"><H3>Como participar</H3><ul className="mt-2 space-y-2 text-sm text-[var(--muted)]"><li>• Proponha com texto claro e custo estimado</li><li>• Discuta por 5 dias de jogo</li><li>• Vote e veja o resultado aplicado na cidade</li></ul></div></div></Section>;
  if(main===27) return <Section kicker="CAPÍTULO 28 • VISÃO GERAL" title="Anti-fraude desde o primeiro clique." sub="O protótipo registra tudo, avisa sobre anúncios suspeitos e trava transferências estranhas. Segurança não é recurso escondido — é interface."><div className="grid sm:grid-cols-3 gap-4">{[['Verificação','Anúncio com selo de origem'],['Alerta','Preço fora do padrão acende aviso'],['Trava','Transferência grande pede confirmação']].map(([a,b])=><div key={a} className="card p-5"><Shield className="text-emerald-300"/><b className="block mt-2">{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div><div className="card p-5"><H3>Modelo blockchain simulado</H3><p className="text-sm text-[var(--muted)] mt-2">Cada ação importante vira um registro encadeado no protótipo: quem, o quê, quando e código do item. Se um registro mudar, o próximo registro denuncia. É assim que o design ensina confiança — sem prometer rede real.</p></div></Section>;
  if(main===28) return <Section kicker="CAPÍTULO 29 • VISÃO GERAL" title="Do documento ao lançamento, em fases." sub="Cada fase tem entrega jogável e teste com a comunidade. Nada de promessa solta: se não dá para jogar, não entra no roadmap."><div className="space-y-3">{[['Fase 1 • Fundação','Cidade, terrenos, carteira e banco simulado'],['Fase 2 • Vida','Profissões, casas, lojas e eventos'],['Fase 3 • RA','Óculos, compra na rua e construção em RA'],['Fase 4 • Cidade viva','DAO, temporadas e economia completa']].map(([a,b],i)=><div key={a} className="card p-5 flex gap-4"><div className="font-display text-2xl font-black neon-text">{String(i+1).padStart(2,'0')}</div><div><b>{a}</b><p className="text-sm text-[var(--muted)]">{b}</p></div></div>)}</div></Section>;
  if(main===29) return <Section kicker="CAPÍTULO 30 • VISÃO GERAL" title="O jogo ganha quando a cidade ganha." sub="Monetização honesta: cosméticos, passe de temporada e taxas claras. Nada que compre vitória — habilidade, tempo e criatividade continuam valendo mais."><div className="grid md:grid-cols-3 gap-4">{[['Cosméticos','Roupas, móveis e efeitos','👕'],['Passe de temporada','Recompensas por jogar','🎫'],['Taxas de mercado','Pequena taxa, visível antes de pagar','🧾']].map(([a,b,e])=><div key={a} className="nft-card p-5"><span className="text-4xl">{e}</span><b className="block mt-3">{a}</b><p className="text-sm text-[var(--muted)] mt-1">{b}</p></div>)}</div><div className="card p-5"><H3>Sustentabilidade</H3><p className="text-sm text-[var(--muted)] mt-2">Parte das taxas financia eventos, recompensas e manutenção. O relatório da DAO mostra para onde o CMG da cidade vai — todo mês de jogo.</p></div></Section>;
  return <Section kicker="CAPÍTULO 31 • VISÃO GERAL" title="Menu completo e como jogar." sub="Tudo conectado. Use o menu lateral para pular para qualquer capítulo e subpágina, ou siga o fluxo abaixo na sua primeira sessão."><div className="card p-5"><H3>Fluxograma da primeira sessão</H3><div className="mt-4 space-y-2">{['Capa → entenda a cidade','Lore → escolha seu bairro','Terreno → simule a compra','Banco → entenda seu CMG','Profissão → calcule o salário','RA → veja a cidade na rua','Cidade → viva, construa, festeje'].map((s,i)=><div key={s} className="flex items-center gap-3"><span className="w-8 h-8 rounded-full bg-gradient-to-r from-[#8b5cf6] to-[#00ff88] text-black flex items-center justify-center font-bold text-sm shrink-0">{i+1}</span><span className="text-sm font-bold">{s}</span></div>)}</div></div><div className="grid sm:grid-cols-2 gap-3">{PAGES.map((p,i)=><button key={p} onClick={()=>goMain(i)} className="card p-3 text-left hover:border-[#8b5cf6]"><span className="text-xs text-cyan-300 font-bold">{String(i+1).padStart(2,'0')} • 3 subpáginas</span><span className="block text-sm font-bold mt-1">{p}</span></button>)}</div><div className="rounded-2xl p-5 bg-emerald-400/10 border border-emerald-300/30"><b>Pronto para jogar?</b><p className="text-sm text-[var(--muted)] mt-1">Volte para o capítulo 5, compre seu primeiro lote simulado e salve no Banco Crypy. A cidade já está te esperando.</p><button className="btn btn-primary mt-3" onClick={()=>goMain(4)}>Ir para o simulador de compra</button></div></Section>;
 };
 const deep=()=>{const d=DEEP[main];return <Section kicker={`CAPÍTULO ${String(main+1).padStart(2,'0')} • 2/3 SISTEMAS & REGRAS • BLOCKCHAIN SIMULADA`} title={`${PAGES[main]} — Sistemas & Regras`} sub={d.desc}><div className="card p-5"><H3>{d.h}</H3><ul className="mt-3 space-y-2 text-sm text-[var(--muted)]">{d.bullets.map(b=><li key={b}>• {b}</li>)}</ul></div><div className="overflow-x-auto card"><table className="w-full min-w-[560px] text-sm"><thead><tr className="text-left border-b border-[var(--line)]">{d.table[0].map(h=><th key={h} className="p-3">{h}</th>)}</tr></thead><tbody>{d.table.slice(1).map((r,i)=><tr key={i} className="border-b border-[var(--line)]">{r.map(c=><td key={c} className="p-3">{c}</td>)}</tr>)}</tbody></table></div><div className="card p-5"><H3>Como isso vira um bloco da cadeia simulada</H3><p className="text-sm text-[var(--muted)] mt-2">Cada ação deste capítulo gera um registro com: jogador, ação, valor em CMG, código do item e hash do bloco anterior. Se alguém tentar mudar um bloco antigo, o hash seguinte não bate — e o jogo mostra o alerta. É assim que o design ensina blockchain sem prometer rede real.</p><div className="mono text-xs mt-3 p-3 rounded-xl bg-black/30 break-all">BLOCO #{flat+1} • HASH 0x{chainHash}… • ANTERIOR 0x{pseudoHash(PAGES[main]+'prev')}… • TIPO: {PAGES[main].toUpperCase()}</div></div><div className="flex flex-wrap gap-2"><button className="btn btn-ghost" onClick={()=>goFlat(flat-1)}>← Subpágina anterior</button><button className="btn btn-primary" onClick={()=>goFlat(flat+1)}>Ir para Na Prática →</button></div></Section>};
 const practice=()=>{const pr=PRACTICE[main];const done=pr.steps.filter((_,i)=>checks[`${main}-${i}`]).length;return <Section kicker={`CAPÍTULO ${String(main+1).padStart(2,'0')} • 3/3 NA PRÁTICA • MISSÃO DO CAPÍTULO`} title={`${PAGES[main]} — Na Prática`} sub="Marque cada passo quando concluir. O checklist é da sua sessão — e o que vale CMG, lote ou save pode ser salvo no Banco Crypy."><div className="card p-5"><div className="flex flex-wrap justify-between gap-2"><div><span className="chip">🎯 MISSÃO</span><H3>{pr.mission}</H3></div><b className="text-emerald-300">{pr.reward}</b></div><div className="progress mt-4"><div style={{width:`${(done/pr.steps.length)*100}%`}}/></div><p className="text-sm text-[var(--muted)] mt-2">{done} de {pr.steps.length} passos concluídos</p><div className="mt-4 space-y-2">{pr.steps.map((s,i)=>{const k=`${main}-${i}`;return <button key={s} onClick={()=>setChecks(c=>({...c,[k]:!c[k]}))} className={`w-full text-left p-3 rounded-xl flex gap-3 items-start ${checks[k]?'bg-emerald-400/10 border border-emerald-300/40':'bg-[var(--surface2)]'}`}>{checks[k]?<CheckSquare className="text-emerald-300 shrink-0 mt-[2px]" size={20}/>:<Square className="text-[var(--muted)] shrink-0 mt-[2px]" size={20}/>}<span className={`text-sm ${checks[k]?'line-through opacity-60':''}`}>{s}</span></button>})}</div>{done===pr.steps.length&&<div className="mt-4 p-3 rounded-xl bg-emerald-400/15 border border-emerald-300/40 text-sm font-bold">Missão completa! Salve sua simulação no Banco Crypy para guardar o progresso.</div>}</div>{main===4&&<div className="card p-5"><H3>Mini-simulador rápido</H3><div className="grid sm:grid-cols-3 gap-3 mt-3"><label className="text-sm font-bold block">Distrito<select className="select mt-1" value={district} onChange={e=>setDistrict(Number(e.target.value))}>{DISTRICTS.map((d,i)=><option key={d.name} value={i}>{d.name}</option>)}</select></label><label className="text-sm font-bold block">Tamanho<select className="select mt-1" value={size} onChange={e=>setSize(Number(e.target.value))}>{[100,250,500,1000].map(s=><option key={s} value={s}>{s} m²</option>)}</select></label><label className="text-sm font-bold block">Raridade<select className="select mt-1" value={rarity} onChange={e=>setRarity(Number(e.target.value))}>{RARITIES.map((r,i)=><option key={r.name} value={i}>{r.name}</option>)}</select></label></div><div className="flex justify-between mt-3"><span>Preço</span><b className="text-emerald-300">{fmtCMG(landPrice)}</b></div><button className="btn btn-primary w-full mt-3" onClick={buyLand}>Comprar neste simulador</button>{msg&&<p className="text-sm mt-2">{msg}</p>}</div>}{main===9&&<div className="card p-5"><H3>Mini-banco rápido</H3><div className="flex flex-wrap gap-2 mt-2"><input className="input !w-[180px]" value={amount} onChange={e=>setAmount(e.target.value)} inputMode="numeric"/><button className="btn btn-primary" onClick={()=>bankAction('deposit')}>Depositar</button><button className="btn btn-cyan" onClick={()=>bankAction('withdraw')}>Sacar</button></div><p className="text-sm mt-2">Saldo: <b>{fmtCMG(balance)}</b> • {msg}</p></div>}{main===15&&<div className="card p-5"><H3>Mini-calculadora rápida</H3><select className="select" value={prof} onChange={e=>setProf(Number(e.target.value))}>{PROFESSIONS.map((p,i)=><option key={p.name} value={i}>{p.name}</option>)}</select><p className="mt-2 text-sm">Nível {level} • {hours}h/semana → <b className="text-emerald-300">{fmtCMG(salary)}/mês</b></p></div>}<div className="card p-5"><H3>Registro em blockchain simulada</H3><p className="text-sm text-[var(--muted)] mt-2">Ao concluir esta missão, o jogo registraria um bloco com seu progresso, recompensa e hash encadeado. Nesta versão de design, o registro aparece abaixo — sem rede real e sem valor financeiro.</p><div className="mono text-xs mt-3 p-3 rounded-xl bg-black/30 break-all">MISSÃO #{main+1} • BLOCO #{flat+1} • 0x{chainHash} • RECOMPENSA: {pr.reward}</div></div></Section>};
 const content=()=>{if(sub===1) return deep(); if(sub===2) return practice(); return overview()};

 return <div data-safe-area-inset-root style={{boxSizing:'border-box',paddingTop:'var(--safe-area-inset-top)',minHeight:'100vh',background:'var(--bg)'}} className="overflow-x-clip">
  <div className="h-[3px] bg-gradient-to-r from-[#8b5cf6] via-[#00e5ff] to-[#00ff88]"/>
  <header data-safe-area-sticky-top style={{top:'var(--safe-area-inset-top)'}} className="sticky z-40 bg-[#050508]/95 backdrop-blur border-b border-[#2b2450]">
   <div className="max-w-[1480px] mx-auto px-3 sm:px-5 h-[68px] flex items-center gap-2 sm:gap-3">
    <button className="btn btn-ghost !p-2 lg:hidden" aria-label="Abrir menu" onClick={()=>setOpen(true)}><Menu size={20}/></button>
    <button onClick={()=>goMain(0)} className="flex items-center gap-2 min-w-0 shrink-0"><span className="w-9 h-9 shrink-0 rounded-xl bg-gradient-to-br from-[#8b5cf6] via-[#00e5ff] to-[#00ff88] text-black flex items-center justify-center font-display font-black text-base">C</span><span className="font-display font-black tracking-wide text-[13px] sm:text-base whitespace-nowrap">CRYPYVERSE <span className="neon-text">NFTGAME</span></span></button>
    <div className="hidden md:flex flex-1 max-w-[360px] relative mx-2"><Search size={17} className="absolute left-3 top-3 text-[var(--muted)]"/><input className="input !pl-9 !rounded-full" placeholder="Buscar NFTs, distritos, profissões…" value={search} onChange={e=>setSearch(e.target.value)}/></div>
    <div className="ml-auto flex items-center gap-1.5 sm:gap-2 min-w-0"><span className="hidden xl:flex chip !py-1.5"><TrendingUp size={13}/> MERCADO NFT • AO VIVO</span><button className="chip !py-1.5 !px-3 shrink-0" onClick={()=>goMain(9)}><Coins size={14}/> <span className="text-emerald-300">{fmtCMG(balance)}</span></button><button className="btn btn-ghost !py-2 !px-3 hidden sm:inline-flex shrink-0" onClick={()=>goMain(9)}><Landmark size={16}/> Banco</button><button className="btn btn-primary !py-2 !px-3 sm:!px-4 shrink-0 text-[13px]" onClick={()=>setWallet(w=>!w)}><Wallet size={16}/>{wallet?'0xCRY…77A1':'Conectar Carteira'}</button></div>
   </div><div className="progress !rounded-none !h-[3px]"><div style={{width:`${((flat+1)/93)*100}%`}}/></div>
  </header>
  {wallet&&<div className="max-w-[1480px] mx-auto px-3 sm:px-5 pt-3"><div className="p-3 rounded-2xl bg-emerald-400/10 border border-emerald-300/30 text-sm flex flex-wrap gap-2 items-center justify-between"><span><b>Carteira simulada conectada:</b> 0xCRYPY77A1 • Rede Crypy (simulada) • {owned.length} NFT(s)</span><button className="btn btn-ghost !py-1.5 !px-3 text-xs" onClick={()=>setWallet(false)}>Desconectar</button></div></div>}
  <div className="max-w-[1480px] mx-auto flex items-start">
   <aside className={`fixed lg:sticky z-50 lg:z-10 inset-y-0 left-0 w-[320px] shrink-0 bg-[#0a0a16] border-r border-[#2b2450] transition-transform duration-300 ${open?'translate-x-0':'-translate-x-full'} lg:translate-x-0`} style={{top:'var(--safe-area-inset-top)'}}>
    <div className="h-full flex flex-col p-3">
     <div className="flex items-center justify-between lg:hidden"><b>Menu NFT • 31 × 3</b><button className="btn btn-ghost !p-2" onClick={()=>setOpen(false)} aria-label="Fechar menu"><X size={18}/></button></div>
     <div className="relative mt-2 lg:hidden"><Search size={17} className="absolute left-3 top-3 text-[var(--muted)]"/><input className="input !pl-9" placeholder="Buscar em 93 páginas…" value={search} onChange={e=>setSearch(e.target.value)}/></div>
     <div className="mt-2 p-3 rounded-2xl bg-gradient-to-br from-[#2a1660] to-[#071a2a] border border-[#3b2f7a]"><div className="flex items-center justify-between"><b className="text-sm">Minha coleção</b><span className="chip !py-1 !bg-black/40 !text-white"><Gem size={12}/> {owned.length} NFTs</span></div><p className="text-xs text-white/70 mt-1">Patrimônio simulado: <b className="text-white">{fmtCMG(balance+owned.reduce((a,l)=>a+l.price,0))}</b></p><button className="btn btn-primary w-full mt-3 !py-2 text-[13px]" onClick={()=>goMain(11)}>Ver carteira</button></div>
     <div className="mt-3"><div className="text-[11px] tracking-widest font-bold text-[var(--muted)] px-1">FILTRAR POR RARIDADE</div><div className="flex flex-wrap gap-1.5 mt-2">{['Todas',...RARITIES.map(r=>r.name)].map(r=><button key={r} onClick={()=>setRarityFilter(r)} className={`chip !text-[11px] ${rarityFilter===r?'!bg-cyan-300 !text-black font-black':''}`}>{r}</button>)}</div></div>
     <div className="text-xs text-[var(--muted)] mt-3 px-1">Capítulo {main+1}/31 • Subpágina {flat+1}/93 • {saveMsg||'Sua simulação pode ser salva.'}</div>
     <nav className="sidebar-scroll overflow-y-auto mt-2 pr-1 flex-1">{search.trim()?filteredFlat.map(f=><button key={f.i} onClick={()=>goFlat(f.i)} className={`w-full text-left p-2.5 rounded-xl flex gap-2 mb-1 ${f.i===flat?'bg-gradient-to-r from-[#8b5cf6] to-[#00e5ff] text-black font-bold':'hover:bg-[var(--surface2)]'}`}><span className="text-xs font-display font-black w-8 shrink-0">{f.i+1}</span><span className="text-[13px] leading-snug [overflow-wrap:anywhere]">{f.title}</span></button>):PAGES.map((p,mi)=><div key={p} className="mb-1"><button onClick={()=>handleMainClick(mi)} className={`w-full text-left p-2.5 rounded-xl flex gap-2 items-center ${mi===main?'bg-[var(--surface2)] border border-[#8b5cf6]/60':'hover:bg-[var(--surface2)]'}`}><span className="text-xs font-display font-black text-cyan-300 w-7 shrink-0">{String(mi+1).padStart(2,'0')}</span><span className="text-[13px] font-bold leading-snug flex-1 [overflow-wrap:anywhere]">{p}</span><span className="text-xs">{expanded===mi?'▾':'▸'}</span></button>{expanded===mi&&<div className="ml-9 mt-1 space-y-1">{SUBS.map((s,si)=>{const fi=mi*3+si;return <button key={s} onClick={()=>goFlat(fi)} className={`w-full text-left p-2 rounded-lg text-[12px] flex gap-2 ${fi===flat?'bg-cyan-300 text-black font-bold':'bg-[var(--surface2)]'}`}><span>{si+1}/3</span><span>{s}</span></button>})}</div>}</div>)}</nav>
     <div className="pt-3 border-t border-[var(--line)]"><button className="btn btn-primary w-full !py-2.5" onClick={saveGame} disabled={saving}><Save size={16}/>{saving?'Salvando…':'Salvar simulação'}</button><div className="p-3 rounded-xl bg-[var(--surface2)] text-xs mt-2"><b className="flex gap-1 items-center"><Link2 size={13}/> CADEIA SIMULADA</b><div className="mono mt-1 break-all">Bloco #{flat+1} • 0x{chainHash}</div><p className="text-[var(--muted)] mt-1">Banco Central: 1 quatrilhão CMG • Sem mintagem real.</p></div></div>
    </div>
   </aside>
   {open&&<button aria-label="Fechar menu" onClick={()=>setOpen(false)} className="fixed inset-0 bg-black/60 z-40 lg:hidden"/>}
   <main className="flex-1 min-w-0 px-3 sm:px-6 lg:px-8 py-5 sm:py-8"><div className="max-w-[920px] mx-auto">{navNote&&<div className="mb-4 p-3 rounded-xl bg-emerald-400/10 border border-emerald-300/30 text-sm">{navNote}</div>}<div className="flex flex-wrap gap-2 mb-4">{SUBS.map((s,si)=><button key={s} onClick={()=>goFlat(main*3+si)} className={`chip ${si===sub?'!bg-cyan-300 !text-black font-bold':''}`}>{si+1}/3 • {s}</button>)}<span className="chip"><Blocks size={13}/> Bloco #{flat+1} • 0x{chainHash}</span><span className="chip"><Crown size={13}/> Protótipo • Blockchain simulada</span></div>{content()}<div className="flex flex-wrap gap-2 mt-8 pt-5 border-t border-[var(--line)]"><button className="btn btn-ghost" disabled={flat===0} onClick={()=>goFlat(flat-1)}><ChevronLeft size={17}/> Anterior</button><span className="self-center text-sm text-[var(--muted)]">Capítulo {main+1}/31 • Subpágina {sub+1}/3 • Página {flat+1}/93</span><button className="btn btn-primary ml-auto" disabled={flat===92} onClick={()=>goFlat(flat+1)}>Próxima página <ChevronRight size={17}/></button></div><footer className="mt-6 pb-4 flex flex-wrap gap-2 items-center text-xs text-[var(--muted)]"><span className="chip"><Gamepad2 size={13}/> CRYPYVERSE NFTGAME • 31 × 3 = 93 páginas</span><span className="chip"><Building2 size={13}/> 7 distritos</span><span className="chip"><Users size={13}/> 20 profissões</span><span className="chip"><Sparkles size={13}/> Blockchain simulada — sem ativos reais</span></footer></div></main>
  </div>
 </div>;
}
